// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/ping", wrapper.SystemPing)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.SystemHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/ready", wrapper.SystemReady)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/version", wrapper.SystemVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/register", wrapper.AuthRegister)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.AuthLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/challenges/{id}/verify", wrapper.AuthVerifyChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/challenges/{id}/resend", wrapper.AuthResendChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/refresh", wrapper.AuthRefresh)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.AuthLogout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/sessions", wrapper.AuthListSessions)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/auth/sessions/{id}", wrapper.AuthRevokeSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.UserGetMe)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/me", wrapper.UserUpdateMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/permissions", wrapper.RbacGetMyPermissions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/preferences", wrapper.UserGetMyPreferences)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/me/preferences", wrapper.UserReplaceMyPreferences)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/roles", wrapper.RbacListRoles)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/users/{id}/roles", wrapper.RbacAssignRole)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/users/{id}/roles/{role}", wrapper.RbacRevokeRole)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/audit-logs", wrapper.AuditSearchLogs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/security-events", wrapper.AuditSearchSecurityEvents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/security-events/{id}/resolve", wrapper.AuditResolveSecurityEvent)
	})

	return r
}

